//! Generate the TypeScript IPC types from the Rust DTOs.
//!
//! The generated file is checked in so the frontend can import it without a
//! build step. CI regenerates it and fails when the result differs, which keeps
//! the Rust and TypeScript contracts from drifting.
//!
//! Run `cargo test --manifest-path src-tauri/Cargo.toml --lib export_ipc_types`
//! after changing a type that crosses the Tauri IPC boundary.

#[cfg(test)]
mod tests {
    use std::fmt::Write as _;
    use std::path::PathBuf;

    use ts_rs::{Config, TS};

    use crate::commands::{
        AccentColor, AlbumOverview, AlbumsView, AppSettings, Appearance, AudioTrackInfo,
        BackupInfo, BatchExportError, BatchExportItem, BatchExportProgress, BatchExportRequest,
        BatchExportResult, CacheKind, CleanupOverview, CleanupRun, ClearCacheResult, CropRect,
        CropState, DefaultAppGroup, DefaultAppTarget, DefaultAppType, DefaultAppsStatus,
        DefaultLayout, DiskSpace, DisplayPreview, DuplicateGroup, EditPreset, EditRecipe,
        EditValues, ExifData, ExportResult, ExternalPlayer, HiddenLockStatus, JunkCategory,
        JunkCategoryReport, JunkCleanResult, JunkFailure, JunkIgnoredItem, JunkItem, JunkSkip,
        JunkTier, LibraryFilterDTO, LibraryFolder, LibraryFootprint, LibraryItemsPage,
        LibraryStats, MediaProbe, OpenPath, PartialSettings, PlaybackConversionProgress,
        PlaybackStrategy, PreparedPlayback, RenderRequest, RestoreResult, RootPathMappingPreview,
        RootPathMappingResult, ScanResult, ScanStatus, SetDefaultOutcome, SkipReason, SmartAlbum,
        SmartAlbumFilter, StartupView, StorageUsage, SubtitleTrackInfo, ThumbnailRequest,
        ThumbnailResponse, ThumbnailSize, TimelineMonth, TrashError, TrashRestoreFailure,
        TrashRestoreItem, TrashRestoreResult, TrashResult, UpdateCheck, ViewerZoomBehavior,
    };
    use crate::errors::{CommandError, ErrorCode};
    use crate::media_kind::MediaKind;
    use crate::models::{Album, MediaItem, Tag};

    fn export_dir() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../src/engine/types/generated")
    }

    #[test]
    fn export_ipc_types() {
        // `i64` is a JavaScript `number` for this app: timestamps are
        // milliseconds and file sizes stay below 2^53.
        let config = Config::new().with_large_int("number");

        let mut output = String::from(
            "// This file is generated by `cargo test --lib export_ipc_types`.\n\
             // Do not edit it by hand; change the Rust DTOs instead.\n\n",
        );

        macro_rules! emit {
            ($($ty:ty),* $(,)?) => {
                $(
                    let declaration = <$ty as TS>::decl(&config);
                    writeln!(output, "export {declaration}\n").expect("write generated type");
                )*
            };
        }

        emit!(
            ErrorCode,
            CommandError,
            Appearance,
            AccentColor,
            StartupView,
            DefaultLayout,
            ThumbnailSize,
            AlbumsView,
            ViewerZoomBehavior,
            MediaKind,
            MediaItem,
            Album,
            Tag,
            ScanResult,
            LibraryFolder,
            OpenPath,
            LibraryFilterDTO,
            LibraryItemsPage,
            LibraryStats,
            ThumbnailRequest,
            ThumbnailResponse,
            ExifData,
            RenderRequest,
            EditValues,
            CropRect,
            CropState,
            ExportResult,
            BatchExportRequest,
            BatchExportItem,
            BatchExportProgress,
            BatchExportResult,
            BatchExportError,
            TrashResult,
            TrashError,
            TrashRestoreItem,
            TrashRestoreFailure,
            TrashRestoreResult,
            DuplicateGroup,
            SmartAlbumFilter,
            SmartAlbum,
            BackupInfo,
            RestoreResult,
            RootPathMappingPreview,
            RootPathMappingResult,
            AlbumOverview,
            EditRecipe,
            EditPreset,
            ExternalPlayer,
            MediaProbe,
            AudioTrackInfo,
            SubtitleTrackInfo,
            PlaybackStrategy,
            PreparedPlayback,
            PlaybackConversionProgress,
            UpdateCheck,
            AppSettings,
            PartialSettings,
            DisplayPreview,
            HiddenLockStatus,
            TimelineMonth,
            StorageUsage,
            CacheKind,
            ClearCacheResult,
            JunkCategory,
            JunkTier,
            ScanStatus,
            SkipReason,
            JunkItem,
            JunkSkip,
            JunkCategoryReport,
            JunkFailure,
            JunkCleanResult,
            JunkIgnoredItem,
            DiskSpace,
            LibraryFootprint,
            CleanupRun,
            CleanupOverview,
            DefaultAppGroup,
            DefaultAppType,
            DefaultAppsStatus,
            DefaultAppTarget,
            SetDefaultOutcome,
        );

        let directory = export_dir();
        std::fs::create_dir_all(&directory).expect("create generated types directory");
        std::fs::write(directory.join("ipc.ts"), output).expect("write generated IPC types");
    }
}
